import {createQuestion} from "./question-model.js";
export async function parseImportFile(file){const text=await file.text();const ext=file.name.split(".").pop().toLowerCase();if(ext==="json"){const data=JSON.parse(text);const rows=Array.isArray(data)?data:data.questions;if(!Array.isArray(rows))throw new Error("JSON must contain an array or a questions array.");return rows.map(row=>createQuestion(row))}if(ext==="csv"){const lines=text.replace(/^\uFEFF/,"").split(/\r?\n/).filter(Boolean);if(lines.length<2)throw new Error("CSV needs a header row and at least one question.");const parse=line=>{const out=[];let v="",q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&q){v+='"';i++}else if(c==='"')q=!q;else if(c===","&&!q){out.push(v);v=""}else v+=c}out.push(v);return out};const headers=parse(lines.shift()).map(x=>x.trim());return lines.map(line=>{const cells=parse(line),row=Object.fromEntries(headers.map((h,i)=>[h,cells[i]||""]));return createQuestion({type:row.type||"single_mcq",subject:row.subject||"",chapter:row.chapter||"",exam:row.exam||"",question:{en:row.question_en||"",hi:row.question_hi||""},options:["A","B","C","D"].map(k=>({id:k,en:row["option_"+k.toLowerCase()+"_en"]||"",hi:row["option_"+k.toLowerCase()+"_hi"]||""})),correct:(row.correct||"A").split("|"),explanation:{en:row.explanation_en||"",hi:row.explanation_hi||""}})})}throw new Error("Supported formats: .csv and .json. Word import will be added with a structured document parser.");}
export const csvTemplate="type,subject,chapter,exam,question_en,question_hi,option_a_en,option_a_hi,option_b_en,option_b_hi,option_c_en,option_c_hi,option_d_en,option_d_hi,correct,explanation_en,explanation_hi\nsingle_mcq,General Knowledge,Geography,SSC CGL,What is the capital of India?,भारत की राजधानी क्या है?,Delhi,दिल्ली,Mumbai,मुंबई,Kolkata,कोलकाता,Chennai,चेन्नई,A,New Delhi is the capital.,नई दिल्ली राजधानी है।";
